alert.src:
const start = new Date().startOf("month");
const end = start.plus(1, "month");

$$.filter(d =>
  d.createdAt >= start &&
  d.createdAt < end &&
  d.client === 0x615d919f1ca8443d56ef9893 &&
  d.direction === "OUT");

$.isAlerted = $.status.history.some(h => h.value === "REVIEWING");

$$.groupBy({
  _id: $.createdAt.format("%Y-%m-%d"),
  alerted: $sum(Number($.isAlerted)),
  total: $sum(1),
}).sortBy("_id");

$.UTC = $._id;
delete $._id;
$.total = $toLong($.total);
$.alerted = $toLong($.alerted);
$.unalerted = $toLong($.total - $.alerted);
$.alertPcnt = ($.alerted / $.total * 100).round(2);

alert.mql:
[
  {
    $set: { "__jsmql.var.start": { $dateTrunc: { date: "$$NOW", unit: "month" } } }
  },
  {
    $set: {
      "__jsmql.var.end": {
        $dateAdd: { startDate: "$__jsmql.var.start", unit: "month", amount: 1 }
      }
    }
  },
  {
    $match: {
      client: new ObjectId("615d919f1ca8443d56ef9893"),
      direction: "OUT",
      $expr: {
        $and: [
          { $gte: ["$createdAt", "$__jsmql.var.start"] },
          { $lt: ["$createdAt", "$__jsmql.var.end"] }
        ]
      }
    }
  },
  {
    $set: {
      isAlerted: {
        $anyElementTrue: {
          $map: {
            input: { $ifNull: ["$status.history", []] },
            as: "h",
            in: { $eq: ["$$h.value", "REVIEWING"] }
          }
        }
      }
    }
  },
  {
    $group: {
      _id: { $dateToString: { date: "$createdAt", format: "%Y-%m-%d" } },
      alerted: { $sum: { $toDouble: "$isAlerted" } },
      total: { $sum: 1 }
    }
  },
  { $sort: { _id: 1 } },
  { $set: { UTC: "$_id" } },
  { $unset: "_id" },
  { $set: { total: { $toLong: "$total" } } },
  { $set: { alerted: { $toLong: "$alerted" } } },
  { $set: { unalerted: { $toLong: { $subtract: ["$total", "$alerted"] } } } },
  {
    $set: {
      alertPcnt: { $round: [{ $multiply: [{ $divide: ["$alerted", "$total"] }, 100] }, 2] }
    }
  }
]

friday.mql:
[
    {
        $set: {
            "address.full": {
                $trim: {
                    // Remove leading/trailing spaces
                    input: {
                        $reduce: {
                            input: {
                                $filter: {
                                    input: [
                                        { $concat: ["$address.building1", " ", "$address.building2"] }, // Combine buildings with a space
                                        {
                                            $cond: [{ $and: ["$address.building1", "$address.building2"] }, ",", ""],
                                        }, // Add comma if both buildings exist
                                        "$address.street",
                                        "$address.city",
                                        "$address.country",
                                    ],
                                    as: "field",
                                    cond: { $ne: ["$$field", ""] }, // Exclude null/empty fields
                                },
                            },
                            initialValue: "",
                            in: {
                                $cond: [
                                    { $eq: ["$$value", ""] },
                                    "$$this", // Add field without separator for the first value
                                    { $concat: ["$$value", " ", "$$this"] }, // Add with a space separator
                                ],
                            },
                        },
                    },
                },
            },
        },
    },
];

